#include <algorithm>
#include <cassert>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>
using namespace std;
// 같은 위치를 먼저 제외한 뒤 남은 색의 개수만 짝짓습니다.
pair<int,int> score(const string& answer,const string& guess){
 if(answer.size()!=guess.size()) throw invalid_argument("length");
 int a[3]={0,0,0},g[3]={0,0,0},hit=0;
 for(size_t i=0;i<answer.size();++i){
  if(answer[i]<'A'||answer[i]>'C'||guess[i]<'A'||guess[i]>'C') throw invalid_argument("alphabet");
  if(answer[i]==guess[i]) ++hit;
  else {++a[answer[i]-'A'];++g[guess[i]-'A'];}
 }
 int near=0;for(int c=0;c<3;++c) near+=min(a[c],g[c]);
 return {hit,near};
}
// 위치가 같은 항목을 지운 뒤 실제 카드 한 장씩 소모하는 독립 기준입니다.
pair<int,int> scoreReference(const string&a,const string&b){
 int hit=0,near=0;vector<char> left;string rest;
 for(size_t i=0;i<a.size();++i) if(a[i]==b[i]) ++hit;else {left.push_back(a[i]);rest+=b[i];}
 for(char c:rest){auto it=find(left.begin(),left.end(),c);if(it!=left.end()){++near;left.erase(it);}}
 return {hit,near};
}
vector<string> strings(const string&alphabet,int maximum){
 vector<string>all(1,""),level(1,"");for(int n=1;n<=maximum;++n){vector<string>next;for(const string&s:level)for(char c:alphabet)next.push_back(s+c);all.insert(all.end(),next.begin(),next.end());level=next;}return all;
}
int main(){size_t cases=0;for(int n=0;n<=5;++n){vector<string>items;for(const string&s:strings("ABC",n))if(static_cast<int>(s.size())==n)items.push_back(s);for(const string&a:items)for(const string&b:items){assert(score(a,b)==scoreReference(a,b));++cases;}}assert(score("AABC","ACAA")==make_pair(1,2));bool bad=false;try{score("A","AA");}catch(const invalid_argument&){bad=true;}assert(bad);bad=false;try{score("D","A");}catch(const invalid_argument&){bad=true;}assert(bad);assert(score(string(100000,'A'),string(100000,'A'))==make_pair(100000,0));cout<<cases<<" cases\n";}
